// ── CONFIG ── replace these once in the n8n editor (stored encrypted).
// Alternatively set them as env vars and read via $env in an expression.
const SUPABASE_URL = 'https://YOUR-PROJECT.supabase.co';
const SERVICE_KEY  = 'PASTE_SUPABASE_SERVICE_ROLE_KEY';

// Webhook v2 nests the posted JSON under `body`.
const src = $json.body || $json;
const savedItemId = src.saved_item_id;
const oembedUrl   = src.oembed_url || null;
const platform    = src.platform || 'manual';

if (!savedItemId) {
  return { json: { ok: false, error: 'missing saved_item_id' } };
}

let oembed = {};
let status = 'complete';

try {
  if (oembedUrl) {
    // Public oembed: TikTok, YouTube, X. Instagram/Facebook need an app token
    // (needs_auth=true) and are handled by a dedicated fetcher — skip here.
    const o = await this.helpers.httpRequest({ method: 'GET', url: oembedUrl, json: true });
    oembed = {
      title: o.title || null,
      author_name: o.author_name || null,
      author_url: o.author_url || null,
      thumbnail_url: o.thumbnail_url || null,
      provider: o.provider_name || platform,
      html: o.html || null
    };
  }
} catch (e) {
  status = 'failed';
  oembed = { fetch_error: String((e && e.message) || e) };
}

// Prefer the user's shared text as the caption; fall back to the oembed title.
const patch = {
  processing_status: status,
  raw_caption: src.text || oembed.title || null,
  source_creator_handle: oembed.author_name || null,
  original_post_data: Object.assign({}, src, { oembed })
};

await this.helpers.httpRequest({
  method: 'PATCH',
  url: `${SUPABASE_URL}/rest/v1/saved_items?id=eq.${savedItemId}`,
  headers: {
    apikey: SERVICE_KEY,
    Authorization: `Bearer ${SERVICE_KEY}`,
    'Content-Type': 'application/json',
    Prefer: 'return=minimal'
  },
  body: patch,
  json: true
});

return { json: { ok: true, saved_item_id: savedItemId, status, oembed } };
